window.GLOSSARY = [
  ["Bean-to-bar", "Fabrication de la fève à la tablette par le même artisan, qui torréfie et broie lui-même."],
  ["Tree-to-bar", "Fabrication sur le lieu même de culture du cacao."],
  ["Grand cru", "Terme marketing (non réglementé) désignant un cacao d'une origine précise et réputée."],
  ["Pure origine", "Cacao d'un seul pays ou d'une seule région."],
  ["Cru de plantation", "Cacao issu d'une seule plantation identifiée."],
  ["Couverture", "Chocolat riche en beurre de cacao (≥ 31 %), destiné aux professionnels."],
  ["Gianduja", "Mélange de chocolat et de pâte de noisettes fine, né à Turin en 1806."],
  ["Praliné", "Fruits secs caramélisés puis broyés."],
  ["Ganache", "Émulsion de chocolat et de crème, cœur des bonbons de chocolatier."],
  ["Blanchiment", "Voile blanc dû à la migration du beurre (gras) ou du sucre (humidité). Inoffensif."],
  ["Snap", "Le claquement net d'une tablette bien tempérée lorsqu'on la casse."],
  ["Grué", "Éclats de fèves torréfiées et décortiquées (nibs)."],
  ["Théobromine", "Alcaloïde du cacao, cousin de la caféine. « Theobroma » signifie « nourriture des dieux »."],
  ["Cabosse", "Le fruit du cacaoyer, qui pousse directement sur le tronc (cauliflorie)."],
  ["Lécithine", "Émulsifiant (souvent de soja ou de tournesol) qui fluidifie le chocolat."],
  ["Pourcentage", "Part de produits du cacao (masse + beurre) dans la tablette. Il ne dit rien de la qualité."],
];

